def hit_rate_mrr(recs, held_out, k):
    if not held_out:
        return 0.0, 0.0
    hits = rr = 0.0
    for user, target in held_out.items():
        top = recs.get(user, [])[:k]             # a missing user simply has an empty list
        if target in top:
            hits += 1
            rr += 1.0 / (top.index(target) + 1)  # positions are 1-based
    n = len(held_out)
    return hits / n, rr / n
